get_seo_configuration.code:
var response = await client.SeoConfiguration.GetSeoConfigurationAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var seoConfiguration = (IReadOnlyDictionary<string, object?>)body["seo_configuration"]!;
var globalStoreSettings = (IReadOnlyDictionary<string, object?>)seoConfiguration["global_store_settings"]!;
Console.WriteLine($"{globalStoreSettings["store_name"]} {globalStoreSettings["title_separator"]}");

patch_seo_configuration.code:
var response = await client.SeoConfiguration.PatchSeoConfigurationAsync(new Dictionary<string, object?>
{
    ["seo_configuration"] = new Dictionary<string, object?>
    {
        ["url_settings"] = new Dictionary<string, object?> { ["regenerate_url_on_item_update"] = true },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var seoConfiguration = (IReadOnlyDictionary<string, object?>)body["seo_configuration"]!;
var urlSettings = (IReadOnlyDictionary<string, object?>)seoConfiguration["url_settings"]!;
Console.WriteLine(urlSettings["regenerate_url_on_item_update"]);

