get_seo_configuration_document_root.code:
var response = await client.SeoConfiguration.GetSeoConfigurationDocumentRootAsync(
    new Dictionary<string, object?> { ["limit"] = 100 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var file in ((IReadOnlyList<object?>)body["items"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{file["config_key"]} {file["file_name"]}");

